function page(title, body) {
    return '<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">' +
        '<title>' + esc(title) + '</title>' +
        '<style>body{font-family:sans-serif;max-width:820px;margin:30px auto;padding:0 16px;color:#22303F}' +
        'table{border-collapse:collapse;width:100%;margin:16px 0}th,td{border:1px solid #ddd;padding:8px;text-align:left;font-size:14px}' +
        'th{background:#0E7C86;color:#fff}.ok{color:#1a7f37;font-weight:700}.bad{color:#b42318;font-weight:700}' +
        'form.inline{display:inline}button{cursor:pointer;border:none;border-radius:4px;padding:5px 10px;font-size:12px;margin:0 2px}' +
        '.revoke{background:#b42318;color:#fff}.reactivate{background:#1a7f37;color:#fff}.rotate{background:#946200;color:#fff}' +
        'fieldset{margin-top:24px;border:1px solid #ccc;border-radius:6px}label{display:block;margin:10px 0}input{padding:6px;margin:4px 0;width:100%;box-sizing:border-box}' +
        '.create{background:#0E7C86;color:#fff;padding:8px 16px;font-size:14px}</style></head>' +
        '<body><h2>🌱 Riego Hub — administración de áreas</h2>' + body + '</body></html>';
}

global.get('pgPool').query('SELECT id, name, status, last_heartbeat_at FROM riego_hub.areas ORDER BY created_at')
    .then(function(result) {
        var rows = result.rows.map(function(a) {
            var estado = a.status === 'revoked' ? '<span class="bad">revocada</span>' : '<span class="ok">activa</span>';
            var hb = a.last_heartbeat_at ? new Date(a.last_heartbeat_at).toLocaleString('es-AR') : 'nunca';
            var toggle = a.status === 'revoked'
                ? '<form class="inline" method="POST" action="/hub/areas/' + esc(a.id) + '/reactivate"><button class="reactivate">Reactivar</button></form>'
                : '<form class="inline" method="POST" action="/hub/areas/' + esc(a.id) + '/revoke"><button class="revoke">Revocar</button></form>';
            var rotate = '<form class="inline" method="POST" action="/hub/areas/' + esc(a.id) + '/rotate-key" onsubmit="return confirm(\'Esto invalida la key actual del area. Confirmar?\');"><button class="rotate">Rotar key</button></form>';
            var estructura = '<a href="/hub/areas/' + esc(a.id) + '/estructura">Estructura</a>';
            return '<tr><td>' + esc(a.id) + '</td><td>' + esc(a.name) + '</td><td>' + estado + '</td><td>' + esc(hb) + '</td><td>' + toggle + ' ' + rotate + ' ' + estructura + '</td></tr>';
        }).join('');
        if (!rows) rows = '<tr><td colspan="5">Todavia no hay areas creadas.</td></tr>';
        var body = '<table><tr><th>ID</th><th>Nombre</th><th>Estado</th><th>Ultimo heartbeat</th><th>Acciones</th></tr>' + rows + '</table>' +
            '<fieldset><legend>Crear area nueva</legend>' +
            '<form method="POST" action="/hub/areas">' +
            '<label>Nombre<input name="name" required placeholder="Ej: Finca Norte"></label>' +
            '<label>ID (opcional, se genera del nombre si se deja vacio)<input name="id" placeholder="Ej: finca-norte"></label>' +
            '<label>Key existente (opcional -- para dar de alta un area que ya tiene una key funcionando, sin rotarla)<input name="existing_key" placeholder="Dejar vacio para generar una key nueva"></label>' +
            '<p><button class="create" type="submit">Crear area</button></p>' +
            '</form></fieldset>';
        msg.statusCode = 200;
        msg.headers = { 'Content-Type': 'text/html; charset=utf-8' };
        msg.payload = page('Riego Hub', body);
        node.send(msg);
    })
    .catch(function(err) {
        msg.statusCode = 500;
        msg.headers = { 'Content-Type': 'text/html; charset=utf-8' };
        msg.payload = page('Error', '<p>Error consultando areas: ' + esc(err.message) + '</p>');
        node.send(msg);
    });
return null;

function esc(s) { return String(s == null ? '' : s).replace(/[&<>"']/g, function(c) { return ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'})[c]; }); }

function renderKeyOncePage(id, name, key, imported) {
    return '<!doctype html><html><head><meta charset="utf-8"><title>Area ' + (imported ? 'importada' : 'creada') + '</title>' +
        '<style>body{font-family:sans-serif;max-width:600px;margin:40px auto;padding:0 16px;color:#22303F}' +
        'code{display:block;background:#f4f4f4;padding:12px;border-radius:6px;word-break:break-all;font-size:14px}</style></head>' +
        '<body><h2>✅ Área "' + esc(name) + '" (' + esc(id) + ') ' + (imported ? 'importada' : 'creada') + '</h2>' +
        '<p><strong>' + (imported ? 'Key confirmada' : 'Nueva key') + ' (copiala ahora, no se vuelve a mostrar):</strong></p>' +
        '<code>' + esc(key) + '</code>' +
        '<p>Poné este valor como <code>RIEGO_AREA_KEY</code> en el <code>.env</code> del Edge de esta área' +
        (imported ? ' (si ya lo tenía configurado así, no hace falta tocar nada).' : ', junto con <code>RIEGO_AREA_ID=' + esc(id) + '</code> y <code>HUB_URL</code> apuntando a este Hub.') +
        '</p><p><a href="/hub/areas">Volver a la lista</a></p></body></html>';
}

var body = msg.payload || {};
var name = (body.name || '').trim();
if (!name) {
    msg.statusCode = 400;
    msg.headers = { 'Content-Type': 'text/html; charset=utf-8' };
    msg.payload = '<p>Falta el nombre del area. <a href="/hub/areas">Volver</a></p>';
    return msg;
}
var areaId = (body.id || '').trim().toLowerCase();
if (!areaId) {
    areaId = name.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '')
        .replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');
}
if (!/^[a-z0-9-]+$/.test(areaId)) {
    msg.statusCode = 400;
    msg.headers = { 'Content-Type': 'text/html; charset=utf-8' };
    msg.payload = '<p>ID invalido (solo minusculas, numeros y guiones). <a href="/hub/areas">Volver</a></p>';
    return msg;
}

var existingKey = (body.existing_key || '').trim();
var key = existingKey || crypto.randomBytes(32).toString('hex');
var keyHash = crypto.createHash('sha256').update(key).digest('hex');

global.get('pgPool').query(
    'INSERT INTO riego_hub.areas (id, name, key_hash) VALUES ($1, $2, $3)',
    [areaId, name, keyHash]
).then(function() {
    msg.statusCode = 200;
    msg.headers = { 'Content-Type': 'text/html; charset=utf-8' };
    msg.payload = renderKeyOncePage(areaId, name, key, !!existingKey);
    node.send(msg);
}).catch(function(err) {
    msg.statusCode = err.code === '23505' ? 409 : 500;
    msg.headers = { 'Content-Type': 'text/html; charset=utf-8' };
    msg.payload = '<p>Error creando el area: ' + esc(err.message) + '</p><p><a href="/hub/areas">Volver</a></p>';
    node.send(msg);
});
return null;

var areaId = msg.req.params.id;
global.get('pgPool').query("UPDATE riego_hub.areas SET status='revoked' WHERE id=$1", [areaId])
    .then(function() { msg.statusCode = 302; msg.headers = { Location: '/hub/areas' }; node.send(msg); })
    .catch(function(err) { msg.statusCode = 500; msg.headers = { 'Content-Type': 'text/plain' }; msg.payload = 'Error: ' + err.message; node.send(msg); });
return null;

var areaId = msg.req.params.id;
global.get('pgPool').query("UPDATE riego_hub.areas SET status='active' WHERE id=$1", [areaId])
    .then(function() { msg.statusCode = 302; msg.headers = { Location: '/hub/areas' }; node.send(msg); })
    .catch(function(err) { msg.statusCode = 500; msg.headers = { 'Content-Type': 'text/plain' }; msg.payload = 'Error: ' + err.message; node.send(msg); });
return null;

