var areaId = msg.req.params.id;
var key = crypto.randomBytes(32).toString('hex');
var keyHash = crypto.createHash('sha256').update(key).digest('hex');
global.get('pgPool').query('UPDATE riego_hub.areas SET key_hash=$1 WHERE id=$2 RETURNING name', [keyHash, areaId])
    .then(function(result) {
        if (!result.rows[0]) {
            msg.statusCode = 404;
            msg.headers = { 'Content-Type': 'text/plain' };
            msg.payload = 'Area no encontrada';
            return node.send(msg);
        }
        msg.statusCode = 200;
        msg.headers = { 'Content-Type': 'text/html; charset=utf-8' };
        msg.payload = renderKeyOncePage(areaId, result.rows[0].name, key, false);
        node.send(msg);
    })
    .catch(function(err) {
        msg.statusCode = 500;
        msg.headers = { 'Content-Type': 'text/plain' };
        msg.payload = 'Error: ' + err.message;
        node.send(msg);
    });
return null;

var body = msg.payload || {};
var areaId = (body.area_id || '').trim();
var areaKey = (body.area_key || '').trim();
if (!areaId || !areaKey) {
    msg.statusCode = 400;
    msg.payload = { ok: false, reason: 'missing_fields' };
    return msg;
}
var keyHash = crypto.createHash('sha256').update(areaKey).digest('hex');
global.get('pgPool').query('SELECT name, key_hash, status, structure_version, structure FROM riego_hub.areas WHERE id=$1', [areaId])
    .then(function(result) {
        var area = result.rows[0];
        if (!area || area.key_hash !== keyHash) {
            msg.statusCode = 401;
            msg.payload = { ok: false, reason: 'invalid_key' };
            return node.send(msg);
        }
        if (area.status === 'revoked') {
            msg.statusCode = 403;
            msg.payload = { ok: false, reason: 'revoked' };
            return node.send(msg);
        }
        var ip = (msg.req.headers['x-forwarded-for'] || (msg.req.connection && msg.req.connection.remoteAddress) || '').toString();
        global.get('pgPool').query(
            'UPDATE riego_hub.areas SET last_heartbeat_at = now(), last_heartbeat_ip = $2 WHERE id = $1',
            [areaId, ip]
        ).finally(function() {
            var clientVersion = Number(body.structure_version) || 0;
            var payload = { ok: true, area_name: area.name, server_time: new Date().toISOString(), structure_version: area.structure_version };
            if (clientVersion !== area.structure_version) {
                payload.structure = area.structure;
            }
            msg.statusCode = 200;
            msg.payload = payload;
            node.send(msg);
        });
    })
    .catch(function(err) {
        msg.statusCode = 500;
        msg.payload = { ok: false, reason: 'internal_error' };
        node.send(msg);
    });
return null;

function loadStructure(areaId) {
    return global.get('pgPool').query('SELECT structure, structure_version FROM riego_hub.areas WHERE id = $1', [areaId])
        .then(function(result) {
            if (!result.rows[0]) return null;
            var s = result.rows[0].structure || {};
            return {
                zonas: Array.isArray(s.zonas) ? s.zonas : [],
                valvulas: Array.isArray(s.valvulas) ? s.valvulas : [],
                sensores: Array.isArray(s.sensores) ? s.sensores : [],
                config: Object.assign({ watchdogMinutos: 60 }, s.config || {}),
                version: result.rows[0].structure_version
            };
        });
}
function saveStructure(areaId, structure) {
    var toSave = { zonas: structure.zonas, valvulas: structure.valvulas, sensores: structure.sensores, config: structure.config };
    return global.get('pgPool').query(
        'UPDATE riego_hub.areas SET structure = $2, structure_version = structure_version + 1 WHERE id = $1',
        [areaId, JSON.stringify(toSave)]
    );
}
function esc(s) { return String(s == null ? '' : s).replace(/[&<>"']/g, function(c) { return ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'})[c]; }); }
global.set('hubLoadStructure', loadStructure);
global.set('hubSaveStructure', saveStructure);
global.set('hubEsc', esc);
return null;

var esc = global.get('hubEsc');

function page(areaId, areaNombre, body) {
    return '<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">' +
        '<title>Estructura - ' + esc(areaNombre) + '</title>' +
        '<style>body{font-family:sans-serif;max-width:900px;margin:30px auto;padding:0 16px;color:#22303F}' +
        'table{border-collapse:collapse;width:100%;margin:10px 0}th,td{border:1px solid #ddd;padding:6px 8px;text-align:left;font-size:13px;vertical-align:top}' +
        'th{background:#0E7C86;color:#fff}h3{margin-top:36px}' +
        'form.inline{display:inline}button{cursor:pointer;border:none;border-radius:4px;padding:5px 10px;font-size:12px;margin:0 2px}' +
        '.del{background:#b42318;color:#fff}.save{background:#1a7f37;color:#fff}.create{background:#0E7C86;color:#fff;padding:8px 16px;font-size:14px}' +
        'fieldset{margin-top:16px;border:1px solid #ccc;border-radius:6px}label{display:block;margin:8px 0;font-size:12px}' +
        'input,select{padding:5px;width:100%;box-sizing:border-box;font-size:13px}' +
        '.editform input, .editform select{width:80px; display:inline-block; margin:0 4px 0 0}</style></head>' +
        '<body><p><a href="/hub/areas">&larr; Areas</a></p>' +
        '<h2>🔧 Estructura de ' + esc(areaNombre) + '</h2>' + body + '</body></html>';
}

var areaId = msg.req.params.id;
global.get('pgPool').query('SELECT name FROM riego_hub.areas WHERE id = $1', [areaId]).then(function(areaResult) {
    if (!areaResult.rows[0]) { msg.statusCode = 404; msg.payload = 'Area no encontrada'; return node.send(msg); }
    var areaNombre = areaResult.rows[0].name;
    global.get('hubLoadStructure')(areaId).then(function(s) {
        var zonasRows = s.zonas.map(function(z) {
            var valvulasDeZona = s.valvulas.filter(function(v) { return v.zonaId === z.id; });
            var valvulasHtml = valvulasDeZona.map(function(v) {
                return '<tr><td colspan="2" style="padding-left:20px;">&#8627; ' + esc(v.nombre) + ' (canal ' + v.canal + ')</td>' +
                    '<td>' +
                    '<form class="inline editform" method="POST" action="/hub/areas/' + esc(areaId) + '/valvulas/' + v.id + '/editar">' +
                    '<input name="nombre" value="' + esc(v.nombre) + '" placeholder="Nombre">' +
                    '<input type="number" name="canal" value="' + v.canal + '" placeholder="Canal">' +
                    '<button class="save" type="submit">Guardar</button></form> ' +
                    '<form class="inline" method="POST" action="/hub/areas/' + esc(areaId) + '/valvulas/' + v.id + '/eliminar" onsubmit="return confirm(\'Eliminar actuador ' + esc(v.nombre).replace(/'/g, "\\'") + '?\');">' +
                    '<button class="del" type="submit">Eliminar</button></form>' +
                    '</td></tr>';
            }).join('');
            return '<tr><td>' + esc(z.nombre) + '</td><td>Unit ' + z.unitid + ' &middot; ' + z.canalesTarjeta + ' canales &middot; max ' + z.maxSimultaneas + ' a la vez</td>' +
                '<td>' +
                '<form class="inline editform" method="POST" action="/hub/areas/' + esc(areaId) + '/zonas/' + z.id + '/editar">' +
                '<input name="nombre" value="' + esc(z.nombre) + '" placeholder="Nombre">' +
                '<input type="number" name="unitid" value="' + z.unitid + '" placeholder="Unit ID">' +
                '<input type="number" name="canalesTarjeta" value="' + z.canalesTarjeta + '" placeholder="Canales">' +
                '<input type="number" name="maxSimultaneas" value="' + z.maxSimultaneas + '" placeholder="Max">' +
                '<button class="save" type="submit">Guardar</button></form> ' +
                '<form class="inline" method="POST" action="/hub/areas/' + esc(areaId) + '/zonas/' + z.id + '/eliminar" onsubmit="return confirm(\'Eliminar zona ' + esc(z.nombre).replace(/'/g, "\\'") + ' y sus actuadores?\');">' +
                '<button class="del" type="submit">Eliminar</button></form>' +
                '</td></tr>' + valvulasHtml;
        }).join('');
        if (!zonasRows) zonasRows = '<tr><td colspan="3">Todavia no hay zonas.</td></tr>';

        var opcionesZonas = s.zonas.map(function(z) { return '<option value="' + z.id + '">' + esc(z.nombre) + ' (Unit ' + z.unitid + ')</option>'; }).join('');

        var sensoresRows = s.sensores.map(function(sn) {
            var origen = sn.fuente === 'mqtt' ? ('MQTT ' + esc(sn.mqttDevEui) + ' / ' + esc(sn.mqttPath)) : ('HA ' + esc(sn.haEntityId));
            return '<tr><td>' + esc(sn.nombre) + '</td><td>' + esc(sn.tipo) + ' (' + esc(sn.unidad) + ')</td><td>' + origen + '</td>' +
                '<td><form class="inline" method="POST" action="/hub/areas/' + esc(areaId) + '/sensores/' + sn.id + '/eliminar" onsubmit="return confirm(\'Eliminar sensor ' + esc(sn.nombre).replace(/'/g, "\\'") + '?\');">' +
                '<button class="del" type="submit">Eliminar</button></form></td></tr>';
        }).join('');
        if (!sensoresRows) sensoresRows = '<tr><td colspan="4">Todavia no hay sensores.</td></tr>';

        var body =
            '<h3>Zonas (tarjetas Modbus)</h3>' +
            '<table><tr><th>Nombre</th><th>Detalle</th><th>Acciones</th></tr>' + zonasRows + '</table>' +
            '<fieldset><legend>Crear zona</legend><form method="POST" action="/hub/areas/' + esc(areaId) + '/zonas">' +
            '<label>Nombre<input name="nombre" required></label>' +
            '<label>Unit ID (Modbus)<input type="number" name="unitid" required></label>' +
            '<label>Canales de la tarjeta<input type="number" name="canalesTarjeta" value="8" required></label>' +
            '<label>Max actuadores a la vez<input type="number" name="maxSimultaneas" value="1"></label>' +
            '<p><button class="create" type="submit">Crear zona</button></p></form></fieldset>' +

            (s.zonas.length ? (
                '<fieldset><legend>Agregar actuador</legend><form method="POST" action="/hub/areas/' + esc(areaId) + '/valvulas">' +
                '<label>Zona<select name="zonaId">' + opcionesZonas + '</select></label>' +
                '<label>Nombre<input name="nombre" required></label>' +
                '<label>Canal (coil)<input type="number" name="canal" required></label>' +
                '<p><button class="create" type="submit">Agregar actuador</button></p></form></fieldset>'
            ) : '<p><em>Cre&aacute; una zona primero para poder agregarle actuadores.</em></p>') +

            '<h3>Sensores</h3>' +
            '<table><tr><th>Nombre</th><th>Tipo</th><th>Origen</th><th>Acciones</th></tr>' + sensoresRows + '</table>' +
            '<fieldset><legend>Crear sensor</legend><form method="POST" action="/hub/areas/' + esc(areaId) + '/sensores">' +
            '<label>Nombre<input name="nombre" required></label>' +
            '<label>Tipo<select name="tipo"><option value="temperatura">Temperatura</option><option value="humedad">Humedad</option><option value="par">PAR (luz)</option><option value="otro">Otro</option></select></label>' +
            '<label>Unidad<input name="unidad" placeholder="&deg;F, %, ..."></label>' +
            '<label>Fuente<select name="fuente"><option value="home_assistant">Home Assistant</option><option value="mqtt">MQTT (Dragino/ChirpStack)</option></select></label>' +
            '<label>Entity ID de Home Assistant (si aplica)<input name="haEntityId" placeholder="sensor.mi_sensor"></label>' +
            '<label>Dev EUI (si es MQTT)<input name="mqttDevEui"></label>' +
            '<label>Campo en el payload (si es MQTT)<input name="mqttPath" placeholder="object.TempC1"></label>' +
            '<p><button class="create" type="submit">Crear sensor</button></p></form></fieldset>' +

            '<h3>Ajustes generales</h3>' +
            '<form method="POST" action="/hub/areas/' + esc(areaId) + '/ajustes">' +
            '<label>Cierre de seguridad (minutos)<input type="number" name="watchdogMinutos" value="' + s.config.watchdogMinutos + '" style="width:100px"></label>' +
            '<p><button class="save" type="submit">Guardar ajustes</button></p></form>' +

            '<p style="color:#5C6B78; font-size:12px; margin-top:30px;">Version de estructura actual: ' + s.version + '. El Edge la toma en su proximo heartbeat (hasta 10 minutos, o al instante si se lo dispara manualmente).</p>';

        msg.statusCode = 200;
        msg.headers = { 'Content-Type': 'text/html; charset=utf-8' };
        msg.payload = page(areaId, areaNombre, body);
        node.send(msg);
    }).catch(function(err) { msg.statusCode = 500; msg.payload = 'Error: ' + err.message; node.send(msg); });
}).catch(function(err) { msg.statusCode = 500; msg.payload = 'Error: ' + err.message; node.send(msg); });
return null;

var esc = global.get('hubEsc');

var areaId = msg.req.params.id;
var body = msg.payload || {};
global.get('hubLoadStructure')(areaId).then(function(s) {
    if (!s) { msg.statusCode = 404; msg.payload = 'Area no encontrada'; return node.send(msg); }
    var nombre = (body.nombre || '').trim();
    var unitid = Number(body.unitid);
    var canalesTarjeta = Number(body.canalesTarjeta);
    var maxSimultaneas = Math.max(1, Number(body.maxSimultaneas) || 1);
    if (!nombre || body.unitid === undefined || body.unitid === '' || isNaN(unitid) || !canalesTarjeta || canalesTarjeta < 1) {
        msg.statusCode = 400; msg.headers = { 'Content-Type': 'text/html; charset=utf-8' };
        msg.payload = '<p>Faltan datos validos. <a href="/hub/areas/' + esc(areaId) + '/estructura">Volver</a></p>';
        return node.send(msg);
    }
    if (s.zonas.some(function(z) { return Number(z.unitid) === unitid; })) {
        msg.statusCode = 409; msg.headers = { 'Content-Type': 'text/html; charset=utf-8' };
